{"command": "cat <<'EOF' > /tmp/patch.json
{
  "spec": {
    "template": {
      "spec": {
        "securityContext": {
          "runAsNonRoot": true,
          "runAsUser": 65534,
          "runAsGroup": 65534,
          "seccompProfile": {"type": "RuntimeDefault"}
        },
        "containers": [
          {
            "name": "app",
            "securityContext": {
              "allowPrivilegeEscalation": false,
              "privileged": false,
              "runAsNonRoot": true,
              "runAsUser": 65534,
              "capabilities": {"drop": ["ALL"]}
            }
          }
        ]
      }
    }
  }
}
EOF
kubectl patch deploy app -n restricted-app --type=strategic --patch-file /tmp/patch.json"}

